class Range(BaseModel):
    """Range: value is the best estimate, low and high estimate the uncertainty (low ≤ value ≤ high). No guarantee that the true value lies in between. Response format of chain v2, planned; field names are preliminary and may change before launch."""

    model_config = ConfigDict(extra="allow", populate_by_name=True, protected_namespaces=())

    value: float = Field(..., description="Best estimate.")
    low: float = Field(..., description="Lower end of the range.")
    high: float = Field(..., description="Upper end of the range.")


