class Component(BaseModel):
    """Component of the dish. In chain v2 as measured, there is exactly one: the whole dish (components_granularity "dish")."""

    model_config = ConfigDict(extra="allow", populate_by_name=True, protected_namespaces=())

    name: str = Field(..., description="Name of the component; with granularity \"dish\" the name of the dish.")
    grams: Range = Field(..., description="Portion of this component in grams, as a range.")
    kcal: Range = Field(..., description="Energy of this component in kcal, as a range.")
    protein_g: float = Field(..., description="Protein in grams, calculated from per_100g and grams.value.")
    carbs_g: float = Field(..., description="Carbohydrates in grams, calculated from per_100g and grams.value.")
    fat_g: float = Field(..., description="Fat in grams, calculated from per_100g and grams.value.")
    kj: Range | None = Field(None, description="Energy in kJ as a range, only with energy_unit kj. kj is calculated per bound from per_100g.kcal (times 4.184), not from the already rounded kcal; it can therefore differ by up to 3 from kcal times 4.184. per_100g.kj has one decimal. oz is grams divided by 28.349523125, to one decimal; total.oz comes from the sum of the grams. kcal and grams always stay in the response, the other units are added.")
    oz: Range | None = Field(None, description="Amount in ounces as a range, only with mass_unit oz: grams divided by 28.349523125, to one decimal.")
    ml: Range | None = Field(None, description="Amount in millilitres, only with volume_unit ml: a range if the source lists its values per 100 ml, otherwise null. Estimates by the model are always null here.")
    nutrients: Nutrients | None = Field(None, description="Extra nutrients for grams.value, only with nutrients eu7 or full: the keys of the chosen scope. null: no data.")
    per_100g: Per100gExtended = Field(..., description="Values per 100 g that the item is calculated with: from the model, calculated from kcal.value and grams.value (kcal to one decimal, macros to two); from your own data, the values of your entry. Send them to /v1/nutrition/correct to recalculate amounts.")


